                        key={`${label}__${index}`}
                        onClick={onActionClick}
                        type="button"
                        size="l"
                        view={view}
                        width="auto"
                    >
                        {label}
                    </Button>
                );
            },
        );

        if (!actions.length) {
            return null;
        }
    } else {
        component = actions?.();

        if (!component) {
            return null;
        }
    }

    return <div className={b('actions')}>{component}</div>;
}

interface RenderIconProps {
    theme?: ToastTheme;
}

