            <div className={b('container')}>
                {hasTitle && <h3 className={b('title')}>{title}</h3>}
                {isClosable && (
                    <Button
                        size="s"
                        view="flat"
                        className={b('btn-close')}
                        onClick={handleClose}
                        aria-label={t('label_close-button')}
